import{_ as n,o as s,c as a,a2 as i}from"./chunks/framework.CPzUcv0I.js";const u=JSON.parse('{"title":"Global System Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"guide/dev/architecture.md","filePath":"guide/dev/architecture.md"}'),o={name:"guide/dev/architecture.md"};function r(t,e,c,l,d,p){return s(),a("div",null,[...e[0]||(e[0]=[i(`<h1 id="global-system-architecture" tabindex="-1">Global System Architecture <a class="header-anchor" href="#global-system-architecture" aria-label="Permalink to &quot;Global System Architecture&quot;">​</a></h1><div style="display:flex;gap:8px;margin:1rem 0;flex-wrap:wrap;"><img src="https://img.shields.io/badge/Runtime-Electron-blue.svg" alt="Electron"><img src="https://img.shields.io/badge/Node.js-24+-green.svg" alt="Node.js"><img src="https://img.shields.io/badge/Model-Isolated%20Processes-orange.svg" alt="Processes"></div><p>Gens-Launcher is the official Graphical User Interface (GUI) of the Gens ecosystem. Built on <strong>Electron</strong>, its primary role is to orchestrate:</p><ol><li>Secure player authentication via Microsoft and Xbox Live APIs.</li><li>Asset verification, dependency downloading, and launching Minecraft via the in-house <code>gens-core</code> engine.</li><li>Asynchronous execution and communication with <strong>Gens-Horizon</strong>, the companion differential cloud sync engine.</li></ol><hr><h2 id="isolated-process-model" tabindex="-1">Isolated Process Model <a class="header-anchor" href="#isolated-process-model" aria-label="Permalink to &quot;Isolated Process Model&quot;">​</a></h2><p>The architecture strictly follows Electron&#39;s process separation model by splitting responsibilities across three isolated realms:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>+-------------------------------------------------------------------+</span></span>
<span class="line"><span>|                        MAIN PROCESS (Node.js)                     |</span></span>
<span class="line"><span>|  - main.js: App lifecycle, windows, global CSP                   |</span></span>
<span class="line"><span>|  - src/main/ipc-auth.js: Mojang proxy, Microsoft tokens           |</span></span>
<span class="line"><span>|  - src/main/ipc-game.js: JVM preparation, child_process execFile  |</span></span>
<span class="line"><span>|  - src/main/ipc-horizon.js: Horizon.exe binary bridge             |</span></span>
<span class="line"><span>|  - src/main/crypto-utils.js: PBKDF2 / AES-256-GCM primitives      |</span></span>
<span class="line"><span>+---------------------------------+---------------------------------+</span></span>
<span class="line"><span>                                  |</span></span>
<span class="line"><span>               Async IPC          | (ipcMain.handle / invoke)</span></span>
<span class="line"><span>               Strict Whitelist   |</span></span>
<span class="line"><span>                                  v</span></span>
<span class="line"><span>+-------------------------------------------------------------------+</span></span>
<span class="line"><span>|                    SECURITY BRIDGE (preload.js)                   |</span></span>
<span class="line"><span>|  - contextIsolation: true                                         |</span></span>
<span class="line"><span>|  - enforceSandbox() / enforceReadSandbox(): Blocks Zip Slip       |</span></span>
<span class="line"><span>|  - window.api: Exclusive surface exposed to the DOM               |</span></span>
<span class="line"><span>+---------------------------------+---------------------------------+</span></span>
<span class="line"><span>                                  |</span></span>
<span class="line"><span>                                  v</span></span>
<span class="line"><span>+-------------------------------------------------------------------+</span></span>
<span class="line"><span>|                   RENDERER PROCESS (Vanilla JS)                   |</span></span>
<span class="line"><span>|  - renderer.js, HTML5, Vanilla CSS                                |</span></span>
<span class="line"><span>|  - Zero direct Node.js access (require() forbidden)               |</span></span>
<span class="line"><span>|  - UI Managers: AccountUI, InstancesUI, ModsUI, CloudUI           |</span></span>
<span class="line"><span>+-------------------------------------------------------------------+</span></span></code></pre></div><hr><h2 id="component-breakdown" tabindex="-1">Component Breakdown <a class="header-anchor" href="#component-breakdown" aria-label="Permalink to &quot;Component Breakdown&quot;">​</a></h2><h3 id="_1-main-process" tabindex="-1">1. Main Process <a class="header-anchor" href="#_1-main-process" aria-label="Permalink to &quot;1. Main Process&quot;">​</a></h3><p>Runs in a full Node.js environment with native file system and low-level network access:</p><ul><li><strong><code>main.js</code></strong>: Application entry point. Instantiates <code>BrowserWindow</code>, enforces global <code>Content-Security-Policy</code> (CSP) headers, and registers IPC handlers.</li><li><strong><code>src/main/ipc-auth.js</code></strong>: Manages OAuth2 flows and acts as a secure reverse proxy for Mojang APIs (skins and capes), bypassing CORS without exposing the renderer.</li><li><strong><code>src/main/ipc-game.js</code></strong>: Launch engine. Builds JVM startup arguments, downloads dependencies, and spawns the game via <code>child_process.execFile</code> (guaranteeing shell-injection immunity).</li><li><strong><code>src/main/ipc-horizon.js</code></strong>: Exclusive communication bridge for <code>Horizon.exe</code>. Validates local binary SHA-256 hash against official GitHub releases (cached for 2 hours) and whitelists executable flags.</li><li><strong><code>src/main/crypto-utils.js</code></strong>: Cryptographic routines. Encryption keys are derived using <strong>PBKDF2</strong> (600,000 iterations with a dedicated 16-byte salt in <code>.key_salt</code>) and authenticated via <strong>AES-256-GCM</strong>.</li></ul><h3 id="_2-the-security-bridge-preload" tabindex="-1">2. The Security Bridge (Preload) <a class="header-anchor" href="#_2-the-security-bridge-preload" aria-label="Permalink to &quot;2. The Security Bridge (Preload)&quot;">​</a></h3><ul><li><strong><code>preload.js</code></strong>: Executes in renderer context but configures boundaries before locking down internal APIs: <ul><li>Exposes a hardened <code>window.api</code> object to the DOM via <code>contextBridge.exposeInMainWorld</code>.</li><li>Implements the <strong>Software Security Shield</strong>: <code>enforceSandbox()</code> and <code>enforceReadSandbox()</code> mathematically inspect all path operations to prevent <code>Zip Slip</code> and <code>Path Traversal</code>.</li><li>Disk write operations are strictly restricted to <code>%AppData%\\GensLauncher</code>.</li><li>File reading outside the sandbox is limited to verified paths (<code>.minecraft/</code>, detected Java runtimes, and temporary directories).</li></ul></li></ul><h3 id="_3-renderer-process-user-interface" tabindex="-1">3. Renderer Process (User Interface) <a class="header-anchor" href="#_3-renderer-process-user-interface" aria-label="Permalink to &quot;3. Renderer Process (User Interface)&quot;">​</a></h3><ul><li><strong><code>renderer.js</code> / HTML / CSS</strong>: Built with lightweight <strong>Vanilla JS</strong> for instant startup and low memory footprint.</li><li>No direct access to <code>require()</code> or <code>process</code>.</li><li>All interactions with the underlying operating system go through asynchronous calls on <code>window.api.invoke()</code>.</li></ul><hr><h2 id="lifecycle-and-asynchronous-performance" tabindex="-1">Lifecycle and Asynchronous Performance <a class="header-anchor" href="#lifecycle-and-asynchronous-performance" aria-label="Permalink to &quot;Lifecycle and Asynchronous Performance&quot;">​</a></h2><ul><li><strong>Zero <code>sendSync</code> Policy:</strong> All blocking operations run asynchronously (<code>ipcRenderer.invoke</code> in renderer and <code>ipcMain.handle</code> in main). The user interface remains reactive even during multi-gigabyte modpack installations.</li><li><strong>Early Environment Injection:</strong> Fundamental system metadata (platform, architecture, version, appData path) is injected into <code>BrowserWindow.additionalArguments</code> during window creation, eliminating synchronous IPC bootstrap calls.</li></ul>`,20)])])}const g=n(o,[["render",r]]);export{u as __pageData,g as default};
